<script lang="ts">
	import { onMount } from 'svelte'; import { createEmployee, employees, updateEmployee } from '$lib/api/employees'; import { services } from '$lib/api/services'; import type { Employee, Service } from '$lib/api/types'; import Button from '$lib/components/ui/Button.svelte'; import Card from '$lib/components/ui/Card.svelte'; import Input from '$lib/components/ui/Input.svelte'; import Alert from '$lib/components/ui/Alert.svelte';
	let items = $state<Employee[]>([]); let offerings = $state<Service[]>([]); let loading = $state(true); let error = $state(''); let name = $state(''); let email = $state(''); let selected = $state<number[]>([]); let editing = $state<Employee | null>(null); let saving = $state(false);
	async function load() { loading = true; try { [items, offerings] = await Promise.all([employees().then((page) => page.content), services().then((page) => page.content)]); } catch (reason) { error = reason instanceof Error ? reason.message : 'Could not load employees.'; } finally { loading = false; } }
	onMount(load); function edit(employee?: Employee) { editing = employee ?? null; name = employee?.name ?? ''; email = employee?.email ?? ''; selected = employee?.services.map((service) => service.id) ?? []; } function toggle(id: number) { selected = selected.includes(id) ? selected.filter((value) => value !== id) : [...selected, id]; }
	async function save() { saving = true; error = ''; try { if (editing) await updateEmployee(editing.id, name, email, selected); else await createEmployee(name, email, selected); edit(); await load(); } catch (reason) { error = reason instanceof Error ? reason.message : 'Could not save employee.'; } finally { saving = false; } }
</script>
<div class="space-y-5"><div><h1 class="text-2xl font-semibold">Employees</h1><p class="text-sm text-slate-600">Assign services to each employee.</p></div>{#if error}<Alert>{error}</Alert>{/if}<div class="grid gap-5 lg:grid-cols-[1fr_20rem]"><Card>{#if loading}<p class="text-sm text-slate-500">Loading employees…</p>{:else}<div class="space-y-3">{#each items as employee}<div class="flex items-center justify-between border-b pb-3"><div><strong>{employee.name}</strong><div class="text-sm text-slate-500">{employee.email} · {employee.services.map((service) => service.name).join(', ') || 'No services'}</div></div><Button variant="outline" onclick={() => edit(employee)}>Edit</Button></div>{/each}</div>{/if}</Card><Card><form class="space-y-3" onsubmit={(event) => { event.preventDefault(); save(); }}><h2 class="font-semibold">{editing ? 'Edit employee' : 'Add employee'}</h2><label class="block text-sm">Name <Input bind:value={name} required /></label><label class="block text-sm">Email <Input bind:value={email} type="email" required /></label><fieldset><legend class="text-sm font-medium">Services</legend>{#each offerings as service}<label class="mt-1 flex items-center gap-2 text-sm"><input type="checkbox" checked={selected.includes(service.id)} onchange={() => toggle(service.id)} /> {service.name}</label>{/each}</fieldset><div class="flex gap-2"><Button type="submit" disabled={saving}>{saving ? 'Saving…' : 'Save'}</Button>{#if editing}<Button variant="outline" onclick={() => edit()}>Cancel</Button>{/if}</div></form></Card></div></div>
